/**
 * Tray states: the B:SPACE character in the tray (menu bar on macOS, the
 * notification area on Windows) shows what the app needs the user to know.
 * The renderer decides the state and sends it over `set-tray-state`; the
 * main process only validates it and swaps the image.
 *
 * The images are generated by `pnpm gen-icons` from assets/brand/tray/,
 * one set per state (see scripts/gen-icons.mjs, TRAY_STATES there must
 * list the same states).
 */

export const TRAY_STATES = ['idle', 'notify', 'screen', 'dnd', 'offline'] as const;

export type TrayState = (typeof TRAY_STATES)[number];

export function isTrayState(value: unknown): value is TrayState {
  return typeof value === 'string' && (TRAY_STATES as readonly string[]).includes(value);
}

/**
 * The resource file for a state on a platform. macOS gets the black
 * template (Electron resolves the @2x by suffix), Windows the multi-size
 * .ico, Linux the 22x22 PNG.
 */
export function trayIconFile(state: TrayState, platform: NodeJS.Platform): string {
  if (platform === 'darwin') return `tray-${state}Template.png`;
  if (platform === 'win32') return `tray-${state}.ico`;
  return `tray-${state}.png`;
}
